 select word,definition,band,domain,example,confusion,contrast,'essential_gap_audit','reviewed',array['essential_gap_audit_12_16_14','app_band_estimated'],reason,now(),'nikl_reference_plus_editorial_estimate_20261012'
 from jsonb_to_recordset($essential_curriculum$[{"word":"특성","definition":"어떤 대상에 두드러지는 성질.","band":2,"domain":"국어","example":"종이와 유리는 물에 젖었을 때의 특성이 달라서, 연구팀은 재료에 맞는 포장 방법을 찾았다.","confusion":"형태","contrast":"특성: 고유한 성질. 형태: 겉으로 보이는 모양.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 1 및 일반 뜻 대조. 앱 단계는 잠정 추정. 특징과 성질을 설명하는 글"},{"word":"적용","definition":"배운 원칙을 알맞은 상황에 사용함.","band":2,"domain":"국어","example":"경기 심판은 친한 선수에게도 같은 규칙을 적용했다. 선수에 따라 기준을 바꾸지 않았다.","confusion":"제정","contrast":"적용: 원칙을 실제로 씀. 제정: 새 규칙을 만듦.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 규칙을 실제 사례에 연결하기"},{"word":"활용","definition":"가지고 있는 것을 쓸모 있게 사용함.","band":2,"domain":"국어","example":"박물관 안내자는 오래된 사진을 활용해 지금과 다른 거리의 모습을 설명했다.","confusion":"보관","contrast":"활용: 쓸모 있게 사용함. 보관: 잘 간직해 둠.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 정보와 도구를 사용하는 설명"},{"word":"탐구","definition":"대상을 깊이 살펴 지식을 구함.","band":3,"domain":"국어","example":"동아리는 물이 새는 수도꼭지의 구조를 탐구했다. 부품이 어떻게 맞물리는지 살피며 원인을 찾았다.","confusion":"추측","contrast":"탐구: 깊이 살피며 알아감. 추측: 근거 없이 짐작함.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 2 및 일반 뜻 대조. 앱 단계는 잠정 추정. 조사 목적과 탐구 활동 이해"},{"word":"답변","definition":"물음에 대한 내용을 밝혀 대답함.","band":2,"domain":"국어","example":"학급은 건의함에 들어온 질문에 답변을 붙였다. 물어본 내용과 관계없는 말을 적지 않았다.","confusion":"질문","contrast":"답변: 물음에 대답함. 질문: 궁금한 것을 물음.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 질문에 맞게 의견 전달하기"},{"word":"의문","definition":"확실하지 않아 궁금하게 여기는 점.","band":2,"domain":"국어","example":"친구들은 그림자 길이가 시간에 따라 바뀌는 까닭에 의문을 갖고, 같은 장소에서 길이를 재어 보았다.","confusion":"확신","contrast":"의문: 궁금하고 확실치 않음. 확신: 틀림없다고 믿음.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 2 및 일반 뜻 대조. 앱 단계는 잠정 추정. 의문과 단순 질문 구별"},{"word":"비용","definition":"어떤 일을 하는 데 드는 돈.","band":2,"domain":"생활","example":"모둠은 책자를 만드는 비용을 줄이려고 꼭 필요한 쪽만 인쇄했다.","confusion":"수입","contrast":"비용: 일에 드는 돈. 수입: 새로 들어온 돈.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 2 및 일반 뜻 대조. 앱 단계는 잠정 추정. 생활 속 지출과 예산 이해"},{"word":"인정하다","definition":"사실이나 가치를 받아들여 옳다고 여김.","band":2,"domain":"국어","example":"의견은 달랐지만 친구가 조사한 자료는 정확했다. 서로의 노력과 사실을 인정하며 대화를 이어 갔다.","confusion":"부정하다","contrast":"인정하다: 옳다고 받아들임. 부정하다: 맞지 않다고 함.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 사실 수용과 가치 인정 구별"},{"word":"명확하다","definition":"내용이나 경계가 분명하다.","band":2,"domain":"국어","example":"발표자는 의견과 확인한 사실을 명확하게 나눠 말했다. 듣는 사람이 둘을 혼동하지 않았다.","confusion":"모호하다","contrast":"명확하다: 뜻과 경계가 분명함. 모호하다: 뜻이 흐릿함.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 애매함과 분명함을 표현하기"},{"word":"침착하다","definition":"당황하지 않고 마음과 행동이 차분하다.","band":2,"domain":"감정·관계","example":"길을 잘못 들었을 때 침착하게 지도를 다시 확인했다. 서둘러 아무 길로나 뛰지 않았다.","confusion":"초조하다","contrast":"침착하다: 당황 않고 차분함. 초조하다: 마음이 조급함.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 2 및 일반 뜻 대조. 앱 단계는 잠정 추정. 위기 상황에서 태도 설명"},{"word":"이론","definition":"현상을 설명하도록 정리한 생각의 체계.","band":3,"domain":"국어","example":"연구팀은 이론에서 예상한 결과가 실제 실험에서도 나타나는지 확인했다. 설명과 증거를 함께 살폈다.","confusion":"추측","contrast":"이론: 현상을 설명하는 체계. 추측: 막연히 짐작한 생각.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 2등급의 동형어 1 및 일반 뜻 대조. 앱 단계는 잠정 추정. 사실·추측·설명을 구별하기"},{"word":"형태","definition":"대상이 이루고 있는 모양.","band":3,"domain":"국어","example":"나뭇잎의 형태를 살펴 둥근 잎과 길쭉한 잎을 구분했다. 잎의 색깔과 모양은 따로 기록했다.","confusion":"기능","contrast":"형태: 이루어진 모양. 기능: 하는 역할.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 모양과 구조를 설명하는 글"},{"word":"기능","definition":"대상이 맡아서 하는 작용이나 역할.","band":3,"domain":"국어","example":"반사띠의 기능은 어두울 때 사람이 더 잘 보이게 하는 것이다. 옷의 장식으로만 여기지 않았다.","confusion":"형태","contrast":"기능: 맡아서 하는 작용. 형태: 겉으로 보이는 모양.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 3 및 일반 뜻 대조. 앱 단계는 잠정 추정. 도구·기관·제도의 역할 이해"},{"word":"개념","definition":"대상에 대해 공통적으로 이해하는 뜻.","band":3,"domain":"국어","example":"지도는 장소 사이의 관계를 나타낸다는 개념을 알고 나니, 교실 배치도도 지도의 한 종류로 이해할 수 있었다.","confusion":"사례","contrast":"개념: 공통 특징으로 아는 뜻. 사례: 구체적인 한 경우.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 설명문에서 핵심 뜻 파악"},{"word":"한계","definition":"능력이나 작용이 미칠 수 있는 범위의 끝.","band":3,"domain":"국어","example":"세 명만 인터뷰한 조사에는 한계가 있다. 그 결과를 모든 사람의 생각이라고 말할 수 없었다.","confusion":"가능성","contrast":"한계: 미칠 수 있는 범위의 끝. 가능성: 실현될 수 있는 정도.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 가능한 범위와 제한 이해"},{"word":"겸손","definition":"자신을 내세우지 않고 남을 존중하는 태도.","band":3,"domain":"감정·관계","example":"친구는 잘 아는 내용에도 모르는 부분이 있을 수 있다고 생각했다. 겸손한 태도로 다른 설명을 들었다.","confusion":"거만","contrast":"겸손: 자기를 낮추고 존중함. 거만: 잘난 체하며 깔봄.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 자신감과 거만함 구별"},{"word":"염려","definition":"좋지 않은 일이 생길까 걱정함.","band":3,"domain":"감정·관계","example":"가족은 늦게 돌아오는 사람을 염려해 안부를 물었다. 혼내기 전에 안전하게 도착했는지 확인했다.","confusion":"기대","contrast":"염려: 나쁜 일이 날까 걱정함. 기대: 좋은 일을 기다림.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 1 및 일반 뜻 대조. 앱 단계는 잠정 추정. 걱정의 대상과 이유 표현"},{"word":"긍지","definition":"자신이나 소속에 대해 느끼는 떳떳한 자부심.","band":3,"domain":"감정·관계","example":"친구는 어려운 규칙을 지키며 경기를 마친 데 긍지를 느꼈다. 다른 팀을 깎아내리지는 않았다.","confusion":"우월감","contrast":"긍지: 떳떳하게 자랑스러움. 우월감: 남보다 낫다고 여김.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 2 및 일반 뜻 대조. 앱 단계는 잠정 추정. 감정의 구체적인 차이 이해"},{"word":"계승","definition":"전해진 가치나 일을 이어 나감.","band":4,"domain":"사회","example":"도제는 스승의 제작 기술을 계승하면서 새로운 재료도 시험했다. 이어 받는 것과 발전시키는 것이 함께 이루어졌다.","confusion":"폐기","contrast":"계승: 전해 온 것을 이어 감. 폐기: 필요 없어 버림.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 2 및 일반 뜻 대조. 앱 단계는 잠정 추정. 전통과 기술의 전승 이해"},{"word":"손실","definition":"가지고 있던 가치나 이익을 잃음.","band":3,"domain":"생활","example":"모둠은 남은 재료를 보관해 다음 작업의 손실을 줄였다. 쓸 수 있는 재료를 함부로 버리지 않았다.","confusion":"이익","contrast":"손실: 가치를 잃어 줄어듦. 이익: 새로 얻은 이득.","reason":"12.16.14 필수 어휘 점검: 미등록 보완. 공식 3등급의 동형어 0 및 일반 뜻 대조. 앱 단계는 잠정 추정. 이익과 피해를 구별하기"},{"word":"복구","definition":"망가진 것을 이전 상태로 되돌림.","band":3,"domain":"생활","example":"관리자는 고장 난 조명을 복구해 전시실이 다시 밝아지게 했다.","confusion":"신설","contrast":"복구: 이전 상태로 되돌림. 신설: 새로 만들어 설치함